recipes.code:
{
  "inputs": [
    {
      "id": "robyn-signer-key",
      "type": "promptString",
      "description": "Optional hex private key. If set, the server signs and submits gasless intents autonomously; if omitted, it returns unsigned intents for the agent/user to sign.",
      "password": true
    }
  ],
  "servers": {
    "robyn": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "anygas-mcp@1.0.2"
      ],
      "env": {
        "ROBYN_SVC": "<robyn-svc>",
        "ROBYN_SIGNER_KEY": "${input:robyn-signer-key}"
      }
    }
  }
}
